<section class="detail-box mt-4"><h3 class="h6">Courier & private details</h3><p class="small muted">Use Edit Order to correct prices or courier cost with a reason and preview, including after delivery. Tracking and private notes are excluded from customer invoices.</p><form wire:submit="saveOperationalDetails" class="row g-3"><div class="col-md-4"><label class="form-label" for="courier-input">Actual courier cost (PKR)</label><x-input class="form-control" id="courier-input" wire:model="courierInput" type="number" min="0" step="0.01" readonly /></div><div class="col-md-8"><label class="form-label" for="tracking-input">Tracking reference</label><x-input class="form-control" id="tracking-input" wire:model="trackingInput" /></div><div class="col-12"><label class="form-label" for="notes-input">Private notes</label><x-textarea class="form-control" id="notes-input" wire:model="notesInput" rows="2"></x-textarea></div><div><button class="btn btn-sage btn-sm" wire:loading.attr="disabled">Save private details</button></div></form></section>
